<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { acknowledgeBusinessAction, listenForBusinessActions, pendingBusinessActions } from '../businessActionSync.js'

const props = defineProps({ page: String, permissions: Array, roles: Array, userId: [Number, String] })
const allowed = new Set(props.permissions || [])
const roleSet = new Set(props.roles || [])
const can = (value) => allowed.has(value)
const page = computed(() => (props.page || '').replace('shipment-', ''))
const shipmentId = Number(window.location.pathname.match(/^\/shipments\/(\d+)/)?.[1] || 0)
const workspace = computed(() => Boolean(shipmentId))
const busy = ref(false)
const error = ref('')
const toast = ref('')
const data = ref(null)
const rows = ref([])
const summary = ref(null)
const reconciliation = ref(null)
const pagination = ref({ total: 0, current_page: 1, last_page: 1 })
const currentPage = ref(1)
const options = ref({ clients: [], accepted_quotations: [], departments: [] })
const search = ref(new URLSearchParams(window.location.search).get('search') || '')
const statusFilter = ref('')
const tab = ref('Overview')
const createOpen = ref(false)
const step = ref(1)
const form = ref({ source_type: roleSet.has('Sales') ? 'accepted_quotation' : 'direct', quotation_id: '', client_id: '', originating_department: ['Operations', 'Transport', 'Forwarding'].find((role) => roleSet.has(role)) || '', inquiry_id: '', shipment_type: 'Import', service_type: '', mode: 'Sea', lcl_fcl: '', origin: '', destination: '', cargo: '', weight_kg: '', quantity: '', volume_cbm: '', planned_departure: '', estimated_delivery: '', currency: '', notes: '', departments: [] })
const customs = ref({ status: 'pending', inspection_status: 'not_required', entry_reference: '', declaration_reference: '', remarks: '' })
const trip = ref({ origin: '', destination: '', provider: '', vehicle: '', plate_number: '', driver_name: '', scheduled_pickup: '', scheduled_delivery: '', remarks: '' })
const booking = ref({ booking_reference: '', carrier: '', vessel: '', voyage_number: '', flight_number: '', port_of_loading: '', port_of_discharge: '', etd: '', eta: '', status: 'pending', remarks: '' })
const container = ref({ container_number: '', size_type: '', seal_number: '', carrier: '', status: 'planned', remarks: '' })
const delivery = ref({ delivered_at: '', delivered_to: '', receiving_representative: '', location: '', quantity_delivered: '', recipient_acknowledged: false, remarks: '' })
const exceptionForm = ref({ severity: 'normal', title: '', description: '' })
const milestone = ref({ department: '', code: '', label: '', status: 'completed', planned_at: '', actual_at: '', remarks: '' })
const assignment = ref({ department: 'Operations', assigned_user_id: '', status: 'assigned', remarks: '' })
const fileForm = ref({ file: null, category: props.page === 'transport-pod' ? 'proof_of_delivery' : 'other', delivery_id: '', remarks: '', expires_on: '' })
const idempotencyKey = ref('')
const milestoneIdempotencyKey = ref('')
const uploadIdempotencyKey = ref('')
const titles = { 'register': 'Shipment Register', 'workspace': 'Shipment Workspace', 'operations-overview': 'Operations Overview', 'operations-jobs': 'Operational Job Queue', 'operations-customs': 'Customs Processing', 'operations-documents': 'Document Checklist', 'operations-milestones': 'Operational Milestones', 'operations-exceptions': 'Shipment Exceptions', 'transport-overview': 'Transport Overview', 'transport-dispatch': 'Dispatch Board', 'transport-assignments': 'Truck Assignments', 'transport-deliveries': 'Pickup & Delivery', 'transport-pod': 'POD Management', 'forwarding-overview': 'Forwarding Overview', 'forwarding-bookings': 'Booking Management', 'forwarding-schedules': 'Carrier Schedules', 'forwarding-containers': 'Container Monitoring', 'forwarding-milestones': 'Forwarding Milestones' }
const title = computed(() => titles[page.value] || (workspace.value ? titles.workspace : titles.register))
const tabs = ['Overview', 'Operations', 'Transport', 'Forwarding', 'Documents', 'Containers & Cargo', 'Milestones', 'Timeline', 'Cost & Funding Status', 'Exceptions', 'History']
const api = async (url, init = {}) => {
  const headers = { Accept: 'application/json', ...(init.body instanceof FormData ? {} : init.body ? { 'Content-Type': 'application/json' } : {}), 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', ...init.headers }
  const response = await fetch(url, { credentials: 'same-origin', ...init, headers })
  const body = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(Object.values(body.errors || {}).flat().join(' ') || body.message || (response.status === 403 ? 'Your role cannot access this shipment action.' : `Request failed (${response.status}).`))
  return body
}
const load = async () => {
  busy.value = true; error.value = ''
  try {
    if (workspace.value) {
      const result = await api(`/api/shipments-workspace/${shipmentId}`)
      data.value = result.data
      data.value.financial_readiness = result.financial_readiness
      customs.value = { ...customs.value, ...(data.value.customs_process?.[0] || {}) }
      const events = await api(`/api/shipments-workspace/${shipmentId}/history`)
      data.value.timeline = events.data; data.value.status_history = events.status_history
      if (can('shipments.assign')) options.value = await api('/api/shipments-workspace/options')
    } else {
      summary.value = (await api('/api/shipments-workspace/dashboard')).data
      if (can('shipment.reconciliation.view')) reconciliation.value = await api('/api/shipments-workspace/reconciliation')
      const params = new URLSearchParams({ per_page: '15', page: String(currentPage.value), ...(search.value ? { search: search.value } : {}), ...(statusFilter.value ? { status: statusFilter.value } : {}) })
      const result = await api(`/api/shipments-workspace?${params}`)
      rows.value = result.data || []
      pagination.value = result.meta || pagination.value
      if (can('shipments.create')) options.value = await api('/api/shipments-workspace/options')
    }
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
const create = async () => {
  try {
    const result = await api('/api/shipments-workspace', { method: 'POST', headers: { 'Idempotency-Key': idempotencyKey.value }, body: JSON.stringify({ ...form.value, idempotency_key: idempotencyKey.value, departments: can('shipments.assign') ? form.value.departments : [] }) })
    toast.value = `${result.data.job_number} registered. ${result.financial_readiness?.note || 'Financial readiness is pending review.'}`
    createOpen.value = false
    window.location.href = `/shipments/${result.data.id}`
  } catch (e) { error.value = e.message }
}
const act = async (suffix, body, method = 'POST') => {
  try { await api(`/api/shipments-workspace/${shipmentId}${suffix}`, { method, body: JSON.stringify(body) }); toast.value = 'Shipment record saved.'; await load() }
  catch (e) { error.value = e.message }
}
const formData = async () => {
  if (!fileForm.value.file) return
  if (!uploadIdempotencyKey.value) uploadIdempotencyKey.value = crypto.randomUUID()
  const payload = new FormData()
  Object.entries({ ...fileForm.value, upload_key: uploadIdempotencyKey.value }).forEach(([key, value]) => { if (value !== null && value !== '') payload.append(key, value) })
  try { await api(`/api/shipments-workspace/${shipmentId}/documents`, { method: 'POST', body: payload }); toast.value = 'Private document uploaded.'; fileForm.value.file = null; uploadIdempotencyKey.value = ''; await load() }
  catch (e) { error.value = e.message }
}
const selectFile = (event) => { fileForm.value.file = event.target.files?.[0] || null }
const selectQuote = () => {
  const quote = options.value.accepted_quotations.find((item) => String(item.id) === String(form.value.quotation_id))
  if (!quote) return
  form.value.client_id = quote.client_id; form.value.inquiry_id = quote.inquiry_id; form.value.currency = quote.currency
  form.value.origin = quote.origin; form.value.destination = quote.destination; form.value.cargo = quote.cargo_description
}
const submitCustoms = () => act('/customs', customs.value, 'PUT')
const addTrip = async () => { await act('/trips', trip.value); trip.value = { origin: '', destination: '', provider: '', vehicle: '', plate_number: '', driver_name: '', scheduled_pickup: '', scheduled_delivery: '', remarks: '' } }
const addBooking = () => act('/bookings', booking.value)
const addContainer = () => act('/containers', container.value)
const addDelivery = () => act('/deliveries', { ...delivery.value, delivered_at: delivery.value.delivered_at || new Date().toISOString() })
const addException = () => act('/exceptions', exceptionForm.value)
const addMilestone = async () => { if (!milestoneIdempotencyKey.value) milestoneIdempotencyKey.value = crypto.randomUUID(); error.value = ''; await act('/milestones', { ...milestone.value, department: milestone.value.department || roleSet.values().next().value, idempotency_key: milestoneIdempotencyKey.value }); if (!error.value) milestoneIdempotencyKey.value = '' }
const assignDepartment = () => act('/assignments', assignment.value)
const updateTrip = (item, status) => api(`/api/shipments-workspace/trips/${item.id}/status`, { method: 'PUT', body: JSON.stringify({ status, expected_version: item.lock_version, actual_pickup: status === 'picked_up' ? new Date().toISOString() : item.actual_pickup, actual_delivery: status === 'delivered' ? new Date().toISOString() : item.actual_delivery, remarks: item.remarks || '' }) }).then(load).catch((e) => { error.value = e.message })
const verifyDoc = (doc, decision) => api(`/api/shipments-workspace/documents/${doc.id}/verify`, { method: 'POST', body: JSON.stringify({ decision, remarks: `${decision.replaceAll('_', ' ')} after review` }) }).then(load).catch((e) => { error.value = e.message })
const nextStep = () => { if (step.value < 7) step.value++ }
const previousStep = () => { if (step.value > 1) step.value-- }
const openWizard = () => { error.value = ''; idempotencyKey.value = crypto.randomUUID(); createOpen.value = true; step.value = 1 }
const departments = ['Operations', 'Transport', 'Forwarding']
const humanDate = (value) => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', ...(value.includes('T') ? { timeStyle: 'short' } : {}) }).format(new Date(value)) : 'Not recorded'
const canEditDepartment = (department) => department === 'Operations' ? can('operations.jobs.manage') : department === 'Transport' ? can('transport.dispatch.manage') : can('forwarding.milestones.manage')
const stopActionSync = listenForBusinessActions(props.userId, 'shipments', async event => {
  await load()
  const shipment = event.actions.find(action => action.entity_type === 'shipment')
  if (shipment) toast.value = `Shipment data refreshed after ${shipment.reference_number} changed.`
})
onBeforeUnmount(stopActionSync)
onMounted(async () => {
  const pendingSyncs = pendingBusinessActions(props.userId, 'shipments')
  await load()
  pendingSyncs.forEach(event => acknowledgeBusinessAction(event.id, props.userId, 'shipments'))
})
</script>

<template>
  <div class="shipment-workspace">
    <header class="shipment-heading"><div><div class="ifc-kicker">INTERFREIGHT GROUP / PHASE 5 · SHIPMENT EXECUTION</div><h1>{{ title }}</h1><p>{{ workspace ? 'One master job record with independent department progress and a shared history.' : 'Register and coordinate master shipment jobs across Operations, Transport and Forwarding.' }}</p></div><button v-if="!workspace && can('shipments.create')" class="ifc-primary" @click="openWizard">+ New Shipment</button><a v-if="workspace" href="/shipments" class="shipment-secondary">Shipment register</a></header>
    <div v-if="error" class="shipment-alert" role="alert">{{ error }} <button @click="load">Retry</button></div><div v-if="toast" class="shipment-success" role="status">{{ toast }}</div>
    <template v-if="!workspace">
      <section class="shipment-kpis"><article><span>MASTER JOBS</span><strong>{{ summary?.master_jobs ?? '—' }}</strong><small>Distinct master shipment records</small></article><article><span>OPERATIONALLY ACTIVE</span><strong>{{ summary?.active_jobs ?? '—' }}</strong><small>Open, in progress or on hold</small></article><article><span>OPERATIONALLY COMPLETED</span><strong>{{ summary?.operationally_completed ?? '—' }}</strong><small>Financial close is separate</small></article><article><span>OPEN EXCEPTIONS</span><strong>{{ summary?.exceptions ?? '—' }}</strong><small>Recorded exceptions only</small></article></section>
      <section v-if="reconciliation" class="shipment-panel"><div class="shipment-toolbar"><div><h2>Department reconciliation</h2><p>{{ reconciliation.explanation }}</p></div><a v-if="can('shipments.view')" href="/shipments">Master register →</a></div><div class="shipment-kpis shipment-reconcile"><article v-for="(count, department) in reconciliation.data" :key="department"><span>{{ department.replaceAll('_', ' ') }}</span><strong>{{ count }}</strong><small>{{ department === 'master_jobs' ? 'Distinct records in master register' : 'Distinct jobs assigned to department' }}</small></article></div></section>
      <section class="shipment-panel"><div class="shipment-toolbar"><div><h2>Master shipment register</h2><p>Commercial baselines remain linked to accepted quotations. {{ summary?.counts_note || '' }}</p></div><div class="shipment-filters"><input v-model="search" placeholder="Search job, client or route" aria-label="Search shipment register" @keydown.enter="currentPage = 1; load()"><select v-model="statusFilter" aria-label="Filter by master status"><option value="">All master statuses</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="on_hold">On hold</option><option value="operationally_completed">Operationally completed</option><option value="cancelled">Cancelled</option></select><button class="shipment-secondary" @click="currentPage = 1; load()">Apply</button></div></div><div class="shipment-table-wrap"><table><thead><tr><th>JOB NUMBER</th><th>CLIENT / SOURCE</th><th>ROUTE</th><th>MODE / SERVICE</th><th>DEPARTMENTS</th><th>MASTER STATUS</th><th>SCHEDULE</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><a :href="`/shipments/${row.id}`" class="shipment-job">{{ row.job_number || row.reference }}</a></td><td>{{ row.customer_name }}<small>{{ row.source_type.replaceAll('_', ' ') }} · {{ row.quotation?.reference || row.inquiry?.reference || 'No commercial source' }}</small></td><td>{{ row.origin }} → {{ row.destination }}</td><td>{{ row.mode }}<small>{{ row.service_type || 'Not recorded' }} · {{ row.lcl_fcl || 'No container class' }}</small></td><td><span v-for="assignment in row.assignments" :key="assignment.department" class="shipment-chip">{{ assignment.department }}</span><span v-if="!row.assignments.length">Unassigned</span></td><td><span class="shipment-status" :class="row.master_status">{{ row.master_status.replaceAll('_', ' ') }}</span></td><td>{{ humanDate(row.planned_departure) }}<small>ETA {{ humanDate(row.estimated_delivery) }}</small></td><td><a :href="`/shipments/${row.id}`" class="shipment-open">Open →</a></td></tr><tr v-if="!rows.length"><td colspan="8" class="shipment-empty">{{ busy ? 'Loading authorized shipment jobs…' : 'No shipment jobs match this view.' }}</td></tr></tbody></table></div><footer class="shipment-pagination"><span>{{ pagination.total || 0 }} jobs · page {{ pagination.current_page || 1 }} of {{ pagination.last_page || 1 }}</span><div><button class="shipment-secondary" :disabled="!pagination.current_page || pagination.current_page <= 1 || busy" @click="currentPage--; load()">Previous</button><button class="shipment-secondary" :disabled="!pagination.last_page || pagination.current_page >= pagination.last_page || busy" @click="currentPage++; load()">Next</button></div></footer></section>
    </template>

    <template v-else-if="data">
      <section class="shipment-hero"><div><span>{{ data.job_number || data.reference }}</span><h2>{{ data.customer_name }}</h2><p>{{ data.origin }} → {{ data.destination }} · {{ data.mode }} · {{ data.service_type || 'Service not recorded' }}</p></div><div class="shipment-hero-state"><span class="shipment-status" :class="data.master_status">{{ data.master_status.replaceAll('_', ' ') }}</span><small>Version {{ data.lock_version }} · {{ data.source_type.replaceAll('_', ' ') }}</small></div></section>
      <nav class="shipment-tabs" aria-label="Shipment sections"><button v-for="name in tabs" :key="name" :class="{ active: tab === name }" @click="tab = name">{{ name }}</button></nav>
      <section v-if="tab === 'Overview'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Shipment overview</h2><dl><dt>Client</dt><dd>{{ data.client?.company_name || data.customer_name }}</dd><dt>Originating department</dt><dd>{{ data.originating_department || 'Legacy record' }}</dd><dt>Service</dt><dd>{{ data.service_type || 'Not recorded' }} · {{ data.shipment_type || 'Type not recorded' }}</dd><dt>Cargo</dt><dd>{{ data.cargo }} · {{ data.weight_kg || 'Weight not recorded' }} kg · {{ data.volume_cbm || 'Volume not recorded' }} cbm</dd><dt>Commercial baseline</dt><dd>{{ data.baseline ? `Accepted ${humanDate(data.baseline.accepted_at)}` : 'Pending; no accepted baseline is linked' }}</dd><dt>Funding readiness</dt><dd>{{ data.financial_readiness?.note || 'Not recorded' }}</dd><dt>ETD / ETA</dt><dd>{{ humanDate(data.planned_departure) }} / {{ humanDate(data.estimated_delivery) }}</dd></dl><div v-if="can('shipments.update')" class="shipment-inline-actions"><button v-if="data.master_status === 'open'" @click="act('/status', { status: 'in_progress', expected_version: data.lock_version, reason: 'Shipment execution started' })">Start shipment</button><button v-if="data.master_status === 'in_progress'" @click="act('/status', { status: 'on_hold', expected_version: data.lock_version, reason: 'Shipment placed on hold for review' })">Place on hold</button><button v-if="data.master_status === 'on_hold'" @click="act('/status', { status: 'in_progress', expected_version: data.lock_version, reason: 'Shipment resumed' })">Resume</button><button v-if="data.master_status === 'in_progress'" @click="act('/status', { status: 'operationally_completed', expected_version: data.lock_version, reason: 'Departmental execution verified as complete' })">Mark operationally completed</button></div><div v-if="can('shipments.assign')" class="shipment-form"><h3>Assign a department</h3><div class="shipment-fields"><label>Department<select v-model="assignment.department"><option v-for="department in departments" :key="department">{{ department }}</option></select></label><label>Department lead<select v-model="assignment.assigned_user_id"><option value="">Unassigned queue</option><option v-for="user in options.users_by_department?.[assignment.department] || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label></div><label>Assignment note<input v-model="assignment.remarks"></label><button class="ifc-primary" @click="assignDepartment">Save assignment</button></div></article><article class="shipment-panel"><h2>Department status</h2><div v-for="department in departments" :key="department" class="shipment-department-row"><span>{{ department }}</span><b>{{ data.assignments.find(row => row.department === department)?.status || 'Not assigned' }}</b><small>{{ data.assignments.find(row => row.department === department)?.assignee?.name || '' }}</small></div><h3>Outstanding requirements</h3><p v-if="!data.documents.length">No shipment documents have been uploaded.</p><p v-else>{{ data.documents.filter(doc => doc.verification_status !== 'verified').length }} document(s) await verification or replacement.</p><p v-if="data.deliveries.some(row => ['pending','uploaded','under_review','rejected','replacement_requested'].includes(row.pod_status))">Delivery POD requires review; this does not close financial workflows.</p></article></section>
      <section v-else-if="tab === 'Operations'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Customs processing</h2><p>{{ data.customs_process?.[0]?.status || 'Pending' }} · {{ data.customs_process?.[0]?.inspection_status || 'Inspection not recorded' }}</p><template v-if="can('operations.customs.manage')"><label>Entry reference<input v-model="customs.entry_reference"></label><label>Declaration reference<input v-model="customs.declaration_reference"></label><label>Status<select v-model="customs.status"><option>pending</option><option>documents_pending</option><option>submitted</option><option>inspection</option><option>on_hold</option><option>released</option><option>not_required</option></select></label><label>Remarks<textarea v-model="customs.remarks"></textarea></label><button class="ifc-primary" @click="submitCustoms">Save customs status</button></template></article><article class="shipment-panel"><h2>Required documents</h2><p>Requirements vary by shipment service and direction. Configure the checklist before treating missing items as blockers.</p><ul><li v-for="doc in data.documents.filter(d => d.category !== 'proof_of_delivery')" :key="doc.id">{{ doc.category.replaceAll('_', ' ') }} · v{{ doc.version }} · {{ doc.verification_status }} <a :href="`/api/shipments-workspace/documents/${doc.id}/download`">Private download</a><button v-if="can('operations.documents.verify') && doc.verification_status === 'pending'" @click="verifyDoc(doc, 'verified')">Verify</button></li></ul></article></section>
      <section v-else-if="tab === 'Transport' || tab === 'Containers & Cargo'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Transport legs</h2><div v-for="item in data.trips" :key="item.id" class="shipment-record-row"><b>{{ item.leg_reference }} · {{ item.status.replaceAll('_', ' ') }}</b><span>{{ item.origin }} → {{ item.destination }}</span><small>{{ item.vehicle || 'Vehicle unassigned' }} · {{ item.plate_number || 'Plate not recorded' }} · {{ item.driver_name || 'Driver not recorded' }}</small><div v-if="can('transport.dispatch.manage')" class="shipment-inline-actions"><button v-if="item.status === 'scheduled'" @click="updateTrip(item, 'dispatched')">Dispatch</button><button v-if="item.status === 'dispatched'" @click="updateTrip(item, 'picked_up')">Record pickup</button><button v-if="item.status === 'picked_up'" @click="updateTrip(item, 'in_transit')">Mark in transit</button><button v-if="item.status === 'in_transit'" @click="updateTrip(item, 'delivered')">Mark delivered</button></div></div><p v-if="!data.trips.length" class="shipment-empty">No transport legs recorded. A master job may have multiple legs.</p><form v-if="can('transport.assignments.manage')" class="shipment-form" @submit.prevent="addTrip"><h3>Schedule another transport leg</h3><div class="shipment-fields"><label>Pickup origin<input v-model="trip.origin" required></label><label>Delivery destination<input v-model="trip.destination" required></label><label>Vehicle<input v-model="trip.vehicle"></label><label>Plate number<input v-model="trip.plate_number"></label><label>Driver name<input v-model="trip.driver_name"></label><label>Provider<input v-model="trip.provider"></label><label>Scheduled pickup<input v-model="trip.scheduled_pickup" type="datetime-local"></label><label>Scheduled delivery<input v-model="trip.scheduled_delivery" type="datetime-local"></label></div><button class="ifc-primary">Add transport leg</button></form></article><article class="shipment-panel"><h2>Delivery confirmations & POD</h2><div v-for="item in data.deliveries" :key="item.id" class="shipment-record-row"><b>{{ item.delivered_to }} · {{ item.pod_status.replaceAll('_', ' ') }}</b><span>{{ humanDate(item.delivered_at) }} · {{ item.location }}</span><small>{{ item.shortages_damages || 'No shortage or damage recorded' }}</small></div><form v-if="can('transport.deliveries.manage')" class="shipment-form" @submit.prevent="addDelivery"><h3>Record a delivery leg</h3><div class="shipment-fields"><label>Delivered to<input v-model="delivery.delivered_to" required></label><label>Receiving representative<input v-model="delivery.receiving_representative"></label><label>Location<input v-model="delivery.location" required></label><label>Delivered at<input v-model="delivery.delivered_at" type="datetime-local"></label><label>Quantity delivered<input v-model="delivery.quantity_delivered" type="number" min="0" step="0.001"></label><label>Shortages / damages<input v-model="delivery.shortages_damages"></label></div><button class="ifc-primary">Record delivery</button></form><form v-if="can('transport.pod.upload')" class="shipment-form" @submit.prevent="formData"><h3>Upload proof of delivery</h3><input type="hidden" v-model="fileForm.category" value="proof_of_delivery"><label>Delivery record<select v-model="fileForm.delivery_id"><option value="">Select if available</option><option v-for="item in data.deliveries" :key="item.id" :value="item.id">{{ item.delivered_to }} · {{ humanDate(item.delivered_at) }}</option></select></label><input type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" @change="selectFile" required><button class="ifc-primary">Upload private POD</button></form></article></section>
      <section v-else-if="tab === 'Forwarding'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Bookings & carrier schedule</h2><div v-for="item in data.bookings" :key="item.id" class="shipment-record-row"><b>{{ item.booking_reference || 'Booking reference not recorded' }} · {{ item.status }}</b><span>{{ item.carrier || 'Carrier not recorded' }} · {{ item.vessel || item.flight_number || 'Vessel / flight not recorded' }}</span><small>ETD {{ humanDate(item.etd) }} · ETA {{ humanDate(item.eta) }}</small></div><form v-if="can('forwarding.bookings.manage')" class="shipment-form" @submit.prevent="addBooking"><h3>Record a booking</h3><div class="shipment-fields"><label>Booking reference<input v-model="booking.booking_reference"></label><label>Carrier<input v-model="booking.carrier"></label><label v-if="data.mode !== 'Air'">Vessel<input v-model="booking.vessel"></label><label v-if="data.mode !== 'Air'">Voyage<input v-model="booking.voyage_number"></label><label v-if="data.mode === 'Air'">Flight number<input v-model="booking.flight_number"></label><label>Port of loading<input v-model="booking.port_of_loading"></label><label>Port of discharge<input v-model="booking.port_of_discharge"></label><label>ETD<input v-model="booking.etd" type="datetime-local"></label><label>ETA<input v-model="booking.eta" type="datetime-local"></label></div><button class="ifc-primary">Save booking</button></form></article><article class="shipment-panel"><h2>Containers</h2><div v-for="item in data.containers" :key="item.id" class="shipment-record-row"><b>{{ item.container_number }} · {{ item.size_type || 'Type not recorded' }}</b><span>Seal {{ item.seal_number || 'Not recorded' }} · {{ item.status }}</span></div><p v-if="!data.containers.length" class="shipment-empty">No container records. Container handling is only required for applicable sea services.</p><form v-if="can('forwarding.containers.manage') && ['Sea','Ocean'].includes(data.mode) && data.lcl_fcl" class="shipment-form" @submit.prevent="addContainer"><h3>Add container</h3><div class="shipment-fields"><label>Container number<input v-model="container.container_number" pattern="[A-Z]{4}[0-9]{7}" maxlength="11" required></label><label>Size / type<input v-model="container.size_type"></label><label>Seal number<input v-model="container.seal_number"></label><label>Carrier<input v-model="container.carrier"></label></div><button class="ifc-primary">Add container</button></form></article></section>
      <section v-else-if="tab === 'Documents'" class="shipment-panel"><h2>Private shipment documents</h2><p>Files remain in private storage; downloads pass through shipment access checks. Replacements create a new version.</p><div v-for="doc in data.documents" :key="doc.id" class="shipment-record-row"><b>{{ doc.original_name }} · v{{ doc.version }}</b><span>{{ doc.category.replaceAll('_', ' ') }} · {{ doc.verification_status }} · {{ humanDate(doc.created_at) }}</span><a :href="`/api/shipments-workspace/documents/${doc.id}/download`">Download</a><div v-if="doc.category === 'proof_of_delivery' && can('transport.pod.verify') && doc.verification_status === 'pending'" class="shipment-inline-actions"><button @click="verifyDoc(doc, 'verified')">Verify POD</button><button @click="verifyDoc(doc, 'rejected')">Reject POD</button><button @click="verifyDoc(doc, 'replacement_requested')">Request replacement</button></div></div><form v-if="can('shipments.documents.upload')" class="shipment-form" @submit.prevent="formData"><h3>Upload document</h3><div class="shipment-fields"><label>Category<select v-model="fileForm.category"><option>commercial_invoice</option><option>packing_list</option><option>bill_of_lading</option><option>air_waybill</option><option>arrival_notice</option><option>delivery_order</option><option>customs_entry</option><option>permit</option><option>release_document</option><option>other</option></select></label><label>Expires on<input v-model="fileForm.expires_on" type="date"></label></div><input type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx" @change="selectFile" required><label>Remarks<input v-model="fileForm.remarks"></label><button class="ifc-primary">Upload private document</button></form></section>
      <section v-else-if="tab === 'Milestones'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Milestone history</h2><div v-for="item in data.milestones" :key="item.id" class="shipment-record-row"><b>{{ item.label }} · {{ item.status }}</b><span>{{ item.department }} · {{ item.actual_at ? humanDate(item.actual_at) : `Planned ${humanDate(item.planned_at)}` }}</span><small>{{ item.remarks }}</small></div></article><form v-if="can('operations.jobs.manage') || can('transport.dispatch.manage') || can('forwarding.milestones.manage')" class="shipment-panel shipment-form" @submit.prevent="addMilestone"><h2>Record milestone</h2><label>Department<select v-model="milestone.department"><option v-for="department in departments.filter(canEditDepartment)" :key="department">{{ department }}</option></select></label><label>Milestone<input v-model="milestone.label" required></label><div class="shipment-fields"><label>Code<input v-model="milestone.code" required></label><label>Status<select v-model="milestone.status"><option>pending</option><option>in_progress</option><option>completed</option><option>delayed</option></select></label><label>Planned at<input v-model="milestone.planned_at" type="datetime-local"></label><label>Actual at<input v-model="milestone.actual_at" type="datetime-local"></label></div><label>Remarks<input v-model="milestone.remarks"></label><button class="ifc-primary">Save milestone</button></form></section>
      <section v-else-if="tab === 'Timeline' || tab === 'History'" class="shipment-panel"><h2>Shipment timeline</h2><p>Append-only events are ordered by occurred timestamp. Corrections should be recorded as new events.</p><ol class="shipment-timeline"><li v-for="event in data.timeline" :key="event.id"><span>{{ event.department || 'IFC' }}</span><div><b>{{ event.event_type.replaceAll('_', ' ') }}</b><p>{{ event.notes }}</p><small>{{ event.actor?.name || 'System' }} · {{ humanDate(event.occurred_at) }}</small></div></li></ol><h3>Status history</h3><div v-for="event in data.status_history" :key="`s${event.id}`" class="shipment-record-row"><b>{{ event.scope }} · {{ event.from_status || 'Created' }} → {{ event.to_status }}</b><span>{{ event.reason }} · {{ humanDate(event.created_at) }}</span></div></section>
      <section v-else-if="tab === 'Cost & Funding Status'" class="shipment-panel"><h2>Commercial and funding readiness</h2><p>Commercial baseline: <b>{{ data.baseline ? `Accepted from ${data.quotation?.reference}` : 'Pending / not linked' }}</b></p><p>Funding status: <b>{{ data.financial_readiness?.funding_status?.replaceAll('_', ' ') || 'Not recorded' }}</b></p><p>{{ data.financial_readiness?.note || 'Funding data is not recorded.' }}</p><div v-for="row in (data.financial_readiness?.estimated_requirement_by_currency || [])" :key="`estimate-${row.currency}`">Approved estimated requirement · {{ row.currency }} {{ row.amount }}</div><div v-for="row in (data.financial_readiness?.allocated_by_currency || [])" :key="`allocated-${row.currency}`">Phase 4 approved allocation · {{ row.currency }} {{ row.amount }}</div><div v-for="row in (data.financial_readiness?.unallocated_requirement_by_currency || [])" :key="`remaining-${row.currency}`">Unallocated estimate requirement · {{ row.currency }} {{ row.amount }}</div><p>Estimated exposure is not a commitment, expense actual or payment. No invoice or financial closing action is performed here.</p><a v-if="data.baseline && can('budgets.view')" href="/accounting/funding-requirements">Review funding requirements</a></section>
      <section v-else-if="tab === 'Exceptions'" class="shipment-detail-grid"><article class="shipment-panel"><h2>Exceptions & delays</h2><div v-for="item in data.exceptions" :key="item.id" class="shipment-record-row"><b>{{ item.title }} · {{ item.severity }} · {{ item.status }}</b><span>{{ item.description }}</span><small>{{ item.resolution || 'No resolution recorded' }}</small><button v-if="item.status === 'open' && can('shipment.exceptions.manage')" @click="act(`/exceptions/${item.id}/resolve`, { resolution: prompt('Resolution note') || '' })">Resolve</button></div></article><form v-if="can('shipment.exceptions.manage')" class="shipment-panel shipment-form" @submit.prevent="addException"><h2>Raise exception</h2><div class="shipment-fields"><label>Severity<select v-model="exceptionForm.severity"><option>low</option><option>normal</option><option>high</option><option>critical</option></select></label><label>Title<input v-model="exceptionForm.title" required></label></div><label>Description<textarea v-model="exceptionForm.description" required></textarea></label><button class="ifc-primary">Raise exception</button></form></section>
    </template>

    <div v-if="createOpen" class="shipment-overlay" @click.self="createOpen = false"><form class="shipment-wizard" @submit.prevent="step === 7 ? create() : nextStep()"><header><div><span>NEW MASTER SHIPMENT · STEP {{ step }} OF 7</span><h2>{{ ['Select Client / Origin', 'Select Source', 'Cargo & Shipment Details', 'Route & Service', 'Department Assignments', 'Schedule & Funding Readiness', 'Review & Create Job'][step - 1] }}</h2></div><button type="button" class="shipment-close" aria-label="Close wizard" @click="createOpen = false">×</button></header><div class="shipment-step-track"><i v-for="n in 7" :key="n" :class="{ active: n <= step }"></i></div><div v-if="step === 1" class="shipment-form"><label>Client<select v-model="form.client_id" required><option value="">Choose client</option><option v-for="client in options.clients" :key="client.id" :value="client.id">{{ client.company_name }} · {{ client.client_type }}</option></select></label><label>Originating department<select v-model="form.originating_department" :disabled="form.source_type === 'accepted_quotation'"><option v-for="department in [...departments, ...(roleSet.has('Sales') ? ['Sales'] : [])]" :key="department">{{ department }}</option></select></label></div><div v-else-if="step === 2" class="shipment-form"><label>Job source<select v-model="form.source_type"><option v-if="roleSet.has('Sales')" value="accepted_quotation">Accepted quotation</option><option v-if="roleSet.has('Operations') || roleSet.has('Transport') || roleSet.has('Forwarding')" value="direct">Direct departmental job</option></select></label><label v-if="form.source_type === 'accepted_quotation'">Accepted quotation<select v-model="form.quotation_id" required @change="selectQuote"><option value="">Choose quotation with active client acceptance</option><option v-for="quote in options.accepted_quotations" :key="quote.id" :value="quote.id">{{ quote.reference }} · {{ quote.company_name }}</option></select></label><p v-else>Direct jobs are recorded without implying client acceptance or an approved commercial baseline. Their commercial and funding readiness remains pending.</p></div><div v-else-if="step === 3" class="shipment-form"><label>Cargo summary<input v-model="form.cargo" required maxlength="220"></label><div class="shipment-fields"><label>Weight kg<input v-model="form.weight_kg" type="number" min="0" step="0.01"></label><label>Quantity<input v-model="form.quantity" type="number" min="0" step="0.001"></label><label>Volume cbm<input v-model="form.volume_cbm" type="number" min="0" step="0.001"></label><label>LCL / FCL<select v-model="form.lcl_fcl"><option value="">Not applicable</option><option>LCL</option><option>FCL</option></select></label></div></div><div v-else-if="step === 4" class="shipment-form"><div class="shipment-fields"><label>Movement type<select v-model="form.shipment_type"><option>Import</option><option>Export</option><option>Domestic</option></select></label><label>Mode<select v-model="form.mode"><option>Sea</option><option>Air</option><option>Land</option><option>Multimodal</option></select></label><label>Service scope<select v-model="form.service_type"><option value="">Choose service</option><option>Operations</option><option>Transport</option><option>Forwarding</option><option>Full Service</option></select></label><label>Origin<input v-model="form.origin" required></label><label>Destination<input v-model="form.destination" required></label></div></div><div v-else-if="step === 5" class="shipment-form"><p>Department responsibilities remain independent after assignment.</p><label v-for="department in departments" :key="department" class="shipment-check"><input v-model="form.departments" type="checkbox" :value="department" :disabled="!can('shipments.assign')">{{ department }}</label></div><div v-else-if="step === 6" class="shipment-form"><div class="shipment-fields"><label>Planned departure<input v-model="form.planned_departure" type="date"></label><label>Expected delivery<input v-model="form.estimated_delivery" type="date"></label><label>Currency reference<input v-model="form.currency" maxlength="3" placeholder="Not set"></label></div><p v-if="form.source_type === 'direct'">Commercial baseline: pending · Funding readiness: pending; no budget allocation will be inferred.</p><p v-else>Accepted commercial baseline is linked through the chosen quotation. Budget readiness must still be checked against Phase 4 allocations.</p></div><div v-else class="shipment-form shipment-review"><dl><dt>Client</dt><dd>{{ options.clients.find(item => String(item.id) === String(form.client_id))?.company_name || 'Not selected' }}</dd><dt>Source</dt><dd>{{ form.source_type === 'accepted_quotation' ? options.accepted_quotations.find(item => String(item.id) === String(form.quotation_id))?.reference || 'Quotation not selected' : `Direct · ${form.originating_department}` }}</dd><dt>Route</dt><dd>{{ form.origin || 'Origin pending' }} → {{ form.destination || 'Destination pending' }}</dd><dt>Service</dt><dd>{{ form.mode }} · {{ form.shipment_type }} · {{ form.service_type || 'Not selected' }} · {{ form.lcl_fcl || 'No container class' }}</dd><dt>Cargo</dt><dd>{{ form.cargo || 'Cargo details pending' }}</dd><dt>Funding</dt><dd>{{ form.source_type === 'accepted_quotation' ? 'Baseline linked, allocation readiness must be checked' : 'Pending commercial and funding review' }}</dd></dl></div><footer><button type="button" class="shipment-secondary" @click="step === 1 ? createOpen = false : previousStep()">{{ step === 1 ? 'Cancel' : 'Back' }}</button><button class="ifc-primary">{{ step === 7 ? 'Create master shipment' : 'Continue' }}</button></footer></form></div>
  </div>
</template>
